__NUXT_JSONP__("/jp/price", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p){return {data:[{details:{slug:b,pageTitle:"料金・授業料について | Mentor Language Institute",pageDescription:c,title:"料金・授業料について",image:"\u002Fimages\u002Fprices\u002Fprice\u002Fprice-jp.jpg",button:{lists:[{link:["\u003Ca class=\"btn btn-primary\" href=\"\u002Fjp\u002Fprice-auto\"\u003E留学費用の自動計算\u003C\u002Fa\u003E"]}]},japanese:{desc:[c,"MLIにお支払い頂く費用は、以下3つ料金の合計額（①+②+③）となります。"],note:[d,"②滞在費（自己手配の場合は不要）","③その他費用（入学金やビザ費など）"],other_desc1:["以下でそれぞれの費用について説明させて頂きますが、\u003Cspan class=\"hutoaka\"\u003Eこちらから実際にいくらの費用がかかるのかが自動で計算出来ます↓\u003C\u002Fspan\u003E"],image:e,other_desc2:["お分かりにならない場合はお気軽にスタッフまでお問合せください。(日本事務局：\u003Ca href=\"tel:03-6692-6731\"\u003E03-6692-6731\u003C\u002Fa\u003E）"]},steps:{title:"①Tuition ＋ ②Accommodation Fee ＋ ③Other fees",subtitle:["If you provide your own accommodation, you do not need to pay the ②Accommodation fee.\u003Cbr\u003E*Please use \u003Ca href=\"\u002Fen\u002Fprice-auto\u002F\"\u003Ethe price calculator\u003C\u002Fa\u003E to get a quote."],lists:[{title:d,subtitle:["当校の授業料金は通常の朝コースでひと月708ドル~1000ドル。\u003Cbr \u002F\u003E\u003Cspan class=\"ymarker\"\u003Eロサンゼルスの語学学校では安い学校のひとつです。\u003C\u002Fspan\u003E","料金はコースや1日に受講する授業の量、通学する期間によって異なります。","\u003Cspan class=\"hutoaka\"\u003E※\u003C\u002Fspan\u003E 受講期間や1日の授業時間により割引が適応されます。"],image:"\u002Fimages\u002Fprices\u002Fprice\u002FPRICE_CHART_WEB_JAN06.jpg",link:["\u003Cb\u003EQ&A\u003C\u002Fb\u003E","\u003Cb\u003EQ1: クレジットカードで支払えますか？ \u003C\u002Fb\u003E \u003Cbr \u002F\u003E\u003Cb\u003EA1:\u003C\u002Fb\u003E はい、クレジットカードでお支払いいただけます。ただし4％の手数料が加算されます。","\u003Cb\u003EQ2: MLI への支払いにはどのような支払い方法が使えますか？ \u003C\u002Fb\u003E \u003Cbr \u002F\u003E\u003Cb\u003EA2:\u003C\u002Fb\u003E 以下のお支払い方法がご利用いただけます： \u003Cbr\u003E • 銀行振込 \u003Cbr\u003E • 国際送金 \u003Cbr\u003E • 現金 \u003Cbr\u003E • 個人小切手 \u003Cbr\u003E • クレジットカード \u003Cbr\u003E • デビットカード \u003Cbr\u003E • Zelle","クレジットカード／デビットカードでのお支払いによる4％のサービス料を避けたい場合は、以下のいずれかの代替方法をお選びいただけます：\u003Cbr\u003E\u003Cb\u003E銀行振込、国際送金（銀行手数料35ドルがかかります）、現金、個人小切手、またはZelle。\u003C\u002Fb\u003E","\u003Cb\u003EQ3: プログラム開始後に授業料を支払うことはできますか？ \u003C\u002Fb\u003E \u003Cbr \u002F\u003E\u003Cb\u003EA3:\u003C\u002Fb\u003E いいえ。授業料はプログラム開始日または開始前に全額支払う必要があります。"]},{title:"②滞在費用",subtitle:["滞在の手配が必要な方はホームステイもしくは学生寮からお選びいただきます。","滞在費は期間による割引はありませんが、\u003Cspan class=\"ymarker\"\u003E空き状況により延長が出来ない場合がありますので、余裕をもった予約をお勧めします。\u003C\u002Fspan\u003E"],category:[{title:"ホームステイの場合の料金",subtitle:["アメリカの文化やネイティブの英語に触れていたい方はホームステイがお勧めです。","\u003Cspan class=\"hutoaka\"\u003E※\u003C\u002Fspan\u003Eホームステイ料金には朝・晩、1日2食の食事が料金に含まれます。"],table:{tableMaxCol:3,tbody:[[f,g,"\u003Cb\u003Eシェア\u003C\u002Fb\u003E"],[h,"$436","$384"],[i,"$872","$768"],[j,"$1,308","$1,152"],[k,"$1,744","$1,536"],[l,"$3,160","$2,904"],[m,"$4,740","$4,356"]]},additional_note:[n],notes:["\u003Cb\u003E\u003C入居時にかかる費用\u003E\u003C\u002Fb\u003E\u003Cbr \u002F\u003E⁻ ホームステイ手配費用：$300\u003Cbr \u002F\u003E⁻ セキュリティデポジット：$300",o,p],description:["料金表は12週間までの記載ですが、それ以上の滞在も可能です。長期間の金額を知りたい方は自動お見積りをご利用ください。"]},{title:"学生寮の場合の料金",subtitle:["他国の学生との交流を大切にしたい方は寮をお勧めしています。","学生寮は30分圏内にバスや電車を通じて通学出来る場所にあり、キッチンが完備されているため、ご自身で料理を準備して頂きます。"],table:{tableMaxCol:4,tbody:[[f,g,"\u003Cb\u003E二人部屋\t\u003C\u002Fb\u003E","\u003Cb\u003E四人部屋\u003C\u002Fb\u003E"],[h,"$570","$430","$315"],[i,"$1,140","$860","$630"],[j,"$1,710","$1,290","$945"],[k,"$2,280","$1,720","$1,260"],[l,"$4,320","$3,080","$2,320"],[m,"$6,480","$4,620","$3,480"]]},additional_note:[n],notes:["\u003Cb\u003E\u003C入居時にかかる費用\u003E\u003C\u002Fb\u003E\u003Cbr \u002F\u003E⁻ 寮手配費用: $200\u003Cbr \u002F\u003E⁻ セキュリティデポジット：$300",o,p],description:["注：滞在先の手配はグループ会社U.S. Support Services Inc.,により運営されています。"]}]},{title:"③その他の諸費用",subtitle:["上記以外には以下の費用がかかります。"],lists:[a,"テキスト代：約200ドル\u002F各レベル","I-20送料：120ドル\u003Cspan class=\"hutoaka\"\u003E※\u003C\u002Fspan\u003E","SEVIS費：350ドル\u003Cspan class=\"hutoaka\"\u003E※\u003C\u002Fspan\u003E"],description:["\u003Cspan class=\"hutoaka\"\u003E※\u003C\u002Fspan\u003Eビザが必要な方のみ"]}]},faq:{title:"留学費用に関するFAQ",questions:["\u003Cspan class=\"huto\"\u003EQ:見積をもらうことは出来ますか？\u003C\u002Fspan\u003E\u003Cbr \u002F\u003EA:はい、\u003Ca href='https:\u002F\u002Fmliesl.edu\u002Fjp\u002Fprice-auto\u002F'\u003Eこちらから \u003C\u002Fa\u003E 自動お見積りが可能です。","\u003Cspan class=\"huto\"\u003EQ:通学してからコースを変更することは出来ますか？\u003C\u002Fspan\u003E\u003Cbr \u002F\u003EA:はい、可能です。","\u003Cspan class=\"huto\"\u003EQ:支払いはどんな方法がありますか？\u003C\u002Fspan\u003E\u003Cbr \u002F\u003EA:入学金はクレジットカードのみ。残金はカード、送金、米国小切手での支払いが可能です。"]},examples:{title:"留学費用の例",subtitle:["以下、4週間の場合と48週間の場合の授業料金例です。"],lists:[{title:"1ヵ月（4週間）の短期留学)",items:[a,"授業料金：1,220ドル","滞在費：1,560（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan style=\"color: #ff0000\"\u003E\u003Cb\u003E合計：3,000ドル\u003C\u002Fb\u003E\u003C\u002Fspan\u003E"]},{title:"1年（48週間）の長期留学)",items:[a,"授業料金：$10,032ドル","滞在費： $13,810（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan style=\"color: #ff0000\"\u003E\u003Cb\u003E合計：23,992ドル\u003C\u002Fb\u003E\u003C\u002Fspan\u003E"]}]},japanese_others:{image:e},dir:"\u002Fprice",path:"\u002Fprice\u002Fjp",extension:".json",createdAt:"2026-10-22T16:31:30.175Z",updatedAt:"2026-03-24T13:34:16.712Z"},lang:b}],fetch:{},mutations:void 0}}("入学金：150ドル","jp","Mentor Language Instituteはロサンゼルスでも費用の安い語学学校のひとつです。このページでは当校に留学した場合の費用について説明します。","①授業料金","\u002Fimages\u002Fprices\u002Fprice\u002Fcalculator-jp.jpg","\u003Cb\u003E期間\u003C\u002Fb\u003E","\u003Cb\u003E一人部屋\u003C\u002Fb\u003E","1 週間","2 週間","3 週間","4 週間","8 週間","12 週間","\u003Cb\u003E18歳未満の生徒様は、家賃が通常料金の約10%上乗せとなります。\u003C\u002Fb\u003E","\u003Cp\u003E\u003Cbr \u002F\u003E\u003C\u002Fp\u003E","\u003Cspan class='hutoaka'\u003E※\u003C\u002Fspan\u003E滞在中に問題がなかった場合、セキュリティデポジットは全額返金されます。")));